-- M2 catalog/configuration foundation; cc_* only.
CREATE TABLE IF NOT EXISTS cc_products_extension (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,legacy_product_id BIGINT UNSIGNED NOT NULL,permanent_id CHAR(36) NOT NULL,product_type VARCHAR(40) NOT NULL DEFAULT 'standard',sales_status VARCHAR(30) NOT NULL DEFAULT 'active',public_title VARCHAR(190) NULL,public_parameters LONGTEXT NULL,created_by_legacy_user_id INT UNSIGNED NULL,created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL,PRIMARY KEY(id),UNIQUE KEY uq_cc_product_permanent(permanent_id),UNIQUE KEY uq_cc_product_legacy(legacy_product_id),KEY idx_cc_product_status(product_type,sales_status)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS cc_materials (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,permanent_id CHAR(36) NOT NULL,material_code VARCHAR(100) NOT NULL,category VARCHAR(80) NOT NULL,brand VARCHAR(100) NULL,model VARCHAR(120) NULL,specification VARCHAR(500) NULL,unit VARCHAR(30) NOT NULL,procurement_price DECIMAL(18,4) NULL,currency CHAR(3) NOT NULL DEFAULT 'CNY',moq DECIMAL(18,3) NOT NULL DEFAULT 0,lead_time_days INT UNSIGNED NOT NULL DEFAULT 0,supplier_name VARCHAR(190) NULL,status VARCHAR(30) NOT NULL DEFAULT 'active',quote_allowed TINYINT(1) NOT NULL DEFAULT 1,public_allowed TINYINT(1) NOT NULL DEFAULT 0,notes VARCHAR(500) NULL,is_test TINYINT(1) NOT NULL DEFAULT 0,created_by_legacy_user_id INT UNSIGNED NULL,created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL,PRIMARY KEY(id),UNIQUE KEY uq_cc_material_permanent(permanent_id),UNIQUE KEY uq_cc_material_code(material_code),KEY idx_cc_material_filter(category,brand,status)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS cc_config_groups (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,permanent_id CHAR(36) NOT NULL,group_code VARCHAR(80) NOT NULL,name VARCHAR(120) NOT NULL,is_required TINYINT(1) NOT NULL DEFAULT 0,is_multiple TINYINT(1) NOT NULL DEFAULT 0,sort_order INT NOT NULL DEFAULT 0,status VARCHAR(30) NOT NULL DEFAULT 'active',created_by_legacy_user_id INT UNSIGNED NULL,created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL,PRIMARY KEY(id),UNIQUE KEY uq_cc_config_group_code(group_code),UNIQUE KEY uq_cc_config_group_pid(permanent_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS cc_config_options (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,group_id BIGINT UNSIGNED NOT NULL,permanent_id CHAR(36) NOT NULL,option_code VARCHAR(100) NOT NULL,name VARCHAR(190) NOT NULL,is_default TINYINT(1) NOT NULL DEFAULT 0,cost_delta DECIMAL(18,4) NOT NULL DEFAULT 0,sales_delta DECIMAL(18,4) NOT NULL DEFAULT 0,moq_delta DECIMAL(18,3) NOT NULL DEFAULT 0,lead_time_days INT NOT NULL DEFAULT 0,material_mapping_json LONGTEXT NULL,status VARCHAR(30) NOT NULL DEFAULT 'active',created_by_legacy_user_id INT UNSIGNED NULL,created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL,PRIMARY KEY(id),UNIQUE KEY uq_cc_config_option_code(group_id,option_code),UNIQUE KEY uq_cc_config_option_pid(permanent_id),KEY idx_cc_config_option_status(group_id,status)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS cc_compatibility_rules (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,permanent_id CHAR(36) NOT NULL,rule_code VARCHAR(100) NOT NULL,name VARCHAR(190) NOT NULL,rule_type VARCHAR(30) NOT NULL,condition_json LONGTEXT NOT NULL,effect_json LONGTEXT NOT NULL,status VARCHAR(30) NOT NULL DEFAULT 'active',created_by_legacy_user_id INT UNSIGNED NULL,created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL,PRIMARY KEY(id),UNIQUE KEY uq_cc_rule_code(rule_code),UNIQUE KEY uq_cc_rule_pid(permanent_id),KEY idx_cc_rule_status(rule_type,status)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
